    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 2, discountPercent: 10 },
      { sku: 'STICKER', qty: 5, discountPercent: 5 },
    ],
  });
  if (!result.ok) throw new Error(`createInvoice failed: ${result.error}`);

  const issued = issueInvoice(result.value, []);
  if (!issued.ok) throw new Error(`issueInvoice failed: ${issued.error}`);

  const summary = vatSummary([issued.value]);

  assert.ok(summary.length > 0);
  // Base should have line discounts applied
  assert.ok(summary.every(e => e.base > 0));
  assert.ok(summary.every(e => e.vat > 0));
});

test('vatSummary with mix of statuses', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  const issued = createIssuedInvoice('C-001', '2024-03-16');

  const totals = invoiceTotals(issued);
  const payment = recordPayment(issued, { amount: totals.total, date: '2024-03-17' });

  const result = vatSummary([draft.value, issued, payment.value]);

  // Should only include issued and paid, not draft
