  const result = lateFee(invoice, '2024-04-25');

  // daysOverdue = 11 (from 2024-04-14 to 2024-04-25)
  const expectedFee = Math.round(due * 11 * 0.0004);
  assert.equal(result, expectedFee);
});

test('lateFee is positive integer', () => {
  const invoice = createIssuedInvoice('C-001', '2024-03-15');
  const result = lateFee(invoice, '2024-05-15');

  assert.ok(Number.isInteger(result));
  assert.ok(result >= 0);
});

test('lateFee with partially paid invoice', () => {
  const invoice = createIssuedInvoice('C-001', '2024-03-15');
  const totals = invoiceTotals(invoice);
  const half = Math.floor(totals.total / 2);

  const payment = recordPayment(invoice, { amount: half, date: '2024-03-16' });
  const result = lateFee(payment.value, '2024-04-15');

  // Fee should be on remaining balance, not full total
  assert.ok(result > 0);
  const remaining = totals.total - half;
  // 1 day overdue (from 2024-04-14 to 2024-04-15)
  const expectedFee = Math.round(remaining * 1 * 0.0004);
  assert.equal(result, expectedFee);
});

test('lateFee with fully paid invoice', () => {
  const invoice = createIssuedInvoice('C-001', '2024-03-15');
  const totals = invoiceTotals(invoice);

  const payment = recordPayment(invoice, { amount: totals.total, date: '2024-03-16' });
  const result = lateFee(payment.value, '2024-04-15');

  // No fee on paid invoice
  assert.equal(result, 0);
});

test('lateFee with zero due amount', () => {
  const invoice = createIssuedInvoice('C-001', '2024-03-15');
  const totals = invoiceTotals(invoice);

  const payment = recordPayment(invoice, { amount: totals.total, date: '2024-03-16' });
  const result = lateFee(payment.value, '2024-05-15');

  assert.equal(result, 0);
});

test('lateFee increases with more days overdue', () => {
  const invoice = createIssuedInvoice('C-001', '2024-03-15');

  const fee10days = lateFee(invoice, '2024-04-24');
  const fee20days = lateFee(invoice, '2024-05-04');

  assert.ok(fee20days > fee10days);
});

test('lateFee increases with larger due amount', () => {
  const inv1 = createIssuedInvoice('C-001', '2024-03-15', 1);
  const inv2 = createIssuedInvoice('C-002', '2024-03-15', '2024-04-14', 10);

  const fee1 = lateFee(inv1, '2024-04-20');
  const fee2 = lateFee(inv2, '2024-04-20');

  assert.ok(fee2 > fee1);
});

test('lateFee with draft invoice before due date', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  // Draft invoices have a dueDate calculated, but if asOf is before that date, fee is 0
  const result = lateFee(draft.value, '2024-03-20');
  assert.equal(result, 0);
});

test('lateFee at exact due date', () => {
  const invoice = createIssuedInvoice('C-001', '2024-03-15');
  const result = lateFee(invoice, invoice.dueDate);

  assert.equal(result, 0);
});

test('lateFee day after due date', () => {
  const invoice = createIssuedInvoice('C-001', '2024-03-15');
  // due date is 2024-04-14
  const result = lateFee(invoice, '2024-04-15');

  const totals = invoiceTotals(invoice);
  const expectedFee = Math.round(totals.total * 1 * 0.0004);
  assert.equal(result, expectedFee);
});

test('lateFee across month boundary', () => {
