  const result = dashboard(invoices, '2024-03-15');

  for (let i = 0; i < result.topCustomers.length - 1; i++) {
    assert.ok(result.topCustomers[i].due >= result.topCustomers[i + 1].due);
  }
});

test('dashboard counts counts partially_paid status', () => {
  const invoice = createIssuedInvoice('C-001', '2024-03-15');
  const totals = invoiceTotals(invoice);
  const half = Math.floor(totals.total / 2);

  const payment = recordPayment(invoice, { amount: half, date: '2024-03-16' });

  const result = dashboard([payment.value], '2024-03-15');

  assert.equal(result.counts.partially_paid, 1);
});

test('dashboard with mixed invoice statuses', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  const issued = issueInvoice(draft.value, []);
  const inv2 = createIssuedInvoice('C-002', '2024-03-15');
  const inv3Paid = recordPayment(createIssuedInvoice('C-003', '2024-03-15'), {
    amount: invoiceTotals(createIssuedInvoice('C-003', '2024-03-15')).total,
    date: '2024-03-16',
  });

  const result = dashboard([draft.value, issued.value, inv2, inv3Paid.value], '2024-03-15');

  assert.equal(result.counts.draft, 1);
  assert.equal(result.counts.issued, 1);
  assert.equal(result.counts.paid, 1);
});

test('dashboard topCustomers with ties', () => {
  const inv1 = createIssuedInvoice('C-001', '2024-03-15', '2024-03-29', 5);
  const inv2 = createIssuedInvoice('C-002', '2024-03-15', '2024-03-29', 5);
  const inv3 = createIssuedInvoice('C-003', '2024-03-15', '2024-03-29', 5);

