test('lateFee calculates 0.04% per day', () => {
  const invoice = createIssuedInvoice('C-001', '2024-03-15');
  const totals = invoiceTotals(invoice);
  const due = totals.total;

  // Invoice due 2024-04-14, asOf 2024-04-15 = 1 day overdue
  const result = lateFee(invoice, '2024-04-15');

  const daysOverdue = Math.floor(
    (new Date('2024-04-15') - new Date('2024-04-14')) / (1000 * 60 * 60 * 24)
  );
  const expectedFee = Math.round(due * daysOverdue * 0.0004);
  assert.equal(result, expectedFee);
});

