  assert.equal(summary[0].base, 9500); // DEV-HOUR unitPrice
});

test('vatSummary with 100 percent discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 100 }],
  });
  if (!result.ok) throw new Error(`createInvoice failed: ${result.error}`);

  const issued = issueInvoice(result.value, []);
  if (!issued.ok) throw new Error(`issueInvoice failed: ${issued.error}`);

  const summary = vatSummary([issued.value]);

  // Base should be 0 with 100% discount
  const entry = summary.find(e => e.rate === 20);
  if (entry) {
    assert.equal(entry.base, 0);
    assert.equal(entry.vat, 0);
  }
});

test('vatSummary with large quantities', () => {
