test('dashboard with empty invoice list', () => {
  const result = dashboard([], '2024-03-15');
  assert.deepEqual(result.counts, { draft: 0, issued: 0, partially_paid: 0, paid: 0 });
  assert.equal(result.outstanding, 0);
  assert.deepEqual(result.overdue, { count: 0, amount: 0 });
  assert.deepEqual(result.topCustomers, []);
});

test('dashboard counts invoices by status', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-03-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  const issued = issueInvoice(draft.value, []);

  const paid = recordPayment(issued.value, { amount: invoiceTotals(issued.value).total, date: '2024-03-16' });

  const invoices = [draft.value, issued.value, paid.value];
  const result = dashboard(invoices, '2024-03-15');

  assert.equal(result.counts.draft, 1);
  assert.equal(result.counts.issued, 1);
  assert.equal(result.counts.paid, 1);
});

