test('dashboard topCustomers returns top 3 by due amount', () => {
  const inv1 = createIssuedInvoice('C-001', '2024-03-15', '2024-03-29', 5);
  const inv2 = createIssuedInvoice('C-002', '2024-03-15', '2024-03-29', 3);
  const inv3 = createIssuedInvoice('C-003', '2024-03-15', '2024-03-29', 10);

  const result = dashboard([inv1, inv2, inv3], '2024-03-15');

  assert.equal(result.topCustomers.length, 3);
  // C-003 should have most due (qty 10), then C-001 (qty 5), then C-002 (qty 3)
  assert.equal(result.topCustomers[0].customerId, 'C-003');
  assert.equal(result.topCustomers[1].customerId, 'C-001');
  assert.equal(result.topCustomers[2].customerId, 'C-002');
});

